export function FieldsetElement({
  legendText = "{{legendText}}",
  inputType = "{{inputType}}",
  accent = "{{accent}}",
  disabled = {{disabled}},
}) {
  return (
    <fieldset disabled={disabled} style={{ width: 300, boxSizing: "border-box", font: "15px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", border: "1.5px solid #24143025", borderRadius: 10, padding: "16px 20px 18px", opacity: disabled ? 0.5 : 1 }}>
      <legend style={{ padding: "0 6px", fontWeight: 700, fontSize: 13, textTransform: "uppercase", letterSpacing: "0.04em", color: accent }}>{legendText}</legend>
      <label style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 0", fontSize: 14 }}>
        <input type={inputType} name="speed" style={{ accentColor: accent, width: 16, height: 16 }} defaultChecked /> Standard (3–5 days)
      </label>
      <label style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 0", fontSize: 14 }}>
        <input type={inputType} name="speed" style={{ accentColor: accent, width: 16, height: 16 }} /> Express (next day)
      </label>
    </fieldset>
  );
}
